const API_ROOT = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/api`;
async function apiRequest(path, options = {}) {
  const response = await fetch(`${API_ROOT}/${path}`, {
    credentials: 'include',
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || data.ok === false) throw new Error(data.message || `API error ${response.status}`);
  return data;
}
async function recordRequest(resource, method = 'GET', data = null, id = '') {
  const query = `records.php?resource=${encodeURIComponent(resource)}${id ? `&id=${encodeURIComponent(id)}` : ''}`;
  return apiRequest(query, { method, ...(data ? { body: JSON.stringify(data) } : {}) });
}

